#include <stdio.h>
#include <time.h>
#include <unistd.h>

#define ITERS 2000000L

int main(void) {
    struct timespec t0, t1;

    /* Always traps: an invalid fd is rejected inside the kernel, never
       served from a fast path (unlike clock_gettime via the vDSO). */
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (long i = 0; i < ITERS; i++)
        write(-1, NULL, 0);
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ns_trap = (t1.tv_sec - t0.tv_sec) * 1e9
                    + (double)(t1.tv_nsec - t0.tv_nsec);

    /* Pure user-space work, same iteration count, for comparison. */
    volatile long sink = 0;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    for (long i = 0; i < ITERS; i++)
        sink += i & 0xff;
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ns_loop = (t1.tv_sec - t0.tv_sec) * 1e9
                    + (double)(t1.tv_nsec - t0.tv_nsec);

    printf("trap (write on bad fd): %.1f ns/call\n", ns_trap / ITERS);
    printf("pure user loop:         %.1f ns/iter\n", ns_loop / ITERS);
    printf("ratio trap/loop:        %.1fx\n", ns_trap / ns_loop);
    return 0;
}
